// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetBatch Get a batch with per-status counts
	// (GET /api/v1/batches/{id})
	GetBatch(ctx context.Context, request GetBatchRequestObject) (GetBatchResponseObject, error)
	// CancelBatch Cancel every pending or scheduled notification in a batch
	// (POST /api/v1/batches/{id}/cancel)
	CancelBatch(ctx context.Context, request CancelBatchRequestObject) (CancelBatchResponseObject, error)
	// ListBatchNotifications List the notifications of a batch
	// (GET /api/v1/batches/{id}/notifications)
	ListBatchNotifications(ctx context.Context, request ListBatchNotificationsRequestObject) (ListBatchNotificationsResponseObject, error)
	// ListNotifications List notifications
	// (GET /api/v1/notifications)
	ListNotifications(ctx context.Context, request ListNotificationsRequestObject) (ListNotificationsResponseObject, error)
	// CreateNotification Create a notification
	// (POST /api/v1/notifications)
	CreateNotification(ctx context.Context, request CreateNotificationRequestObject) (CreateNotificationResponseObject, error)
	// CreateNotificationBatch Create up to 1000 notifications at once
	// (POST /api/v1/notifications/batch)
	CreateNotificationBatch(ctx context.Context, request CreateNotificationBatchRequestObject) (CreateNotificationBatchResponseObject, error)
	// GetNotification Get a notification with its delivery attempts
	// (GET /api/v1/notifications/{id})
	GetNotification(ctx context.Context, request GetNotificationRequestObject) (GetNotificationResponseObject, error)
	// CancelNotification Cancel a pending or scheduled notification
	// (POST /api/v1/notifications/{id}/cancel)
	CancelNotification(ctx context.Context, request CancelNotificationRequestObject) (CancelNotificationResponseObject, error)
	// RetryNotification Re-queue a failed notification
	// (POST /api/v1/notifications/{id}/retry)
	RetryNotification(ctx context.Context, request RetryNotificationRequestObject) (RetryNotificationResponseObject, error)
	// ListTemplates List templates
	// (GET /api/v1/templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// CreateTemplate Create a template
	// (POST /api/v1/templates)
	CreateTemplate(ctx context.Context, request CreateTemplateRequestObject) (CreateTemplateResponseObject, error)
	// DeleteTemplate Delete a template
	// (DELETE /api/v1/templates/{id})
	DeleteTemplate(ctx context.Context, request DeleteTemplateRequestObject) (DeleteTemplateResponseObject, error)
	// GetTemplate Get a template
	// (GET /api/v1/templates/{id})
	GetTemplate(ctx context.Context, request GetTemplateRequestObject) (GetTemplateResponseObject, error)
	// UpdateTemplate Replace a template
	// (PUT /api/v1/templates/{id})
	UpdateTemplate(ctx context.Context, request UpdateTemplateRequestObject) (UpdateTemplateResponseObject, error)
	// PreviewTemplate Render a template without sending anything
	// (POST /api/v1/templates/{id}/preview)
	PreviewTemplate(ctx context.Context, request PreviewTemplateRequestObject) (PreviewTemplateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

